function goTo(toF, toR)
  while f < toF do
    byte.forward()
    f = f + 1
  end
  while f > toF do
    byte.back()
    f = f + -1
  end
  byte.turnRight()
  while r < toR do
    byte.forward()
    r = r + 1
  end
  while r > toR do
    byte.back()
    r = r + -1
  end
  byte.turnLeft()
end



